import { desc, eq, inArray, sql, sum, asc } from 'drizzle-orm'
import { createDirectSaleInputSchema } from '@pi-skeleton/shared/validations/sales'
import { computeLineTotals } from '@shared/lib/pricing.js'

// ============================================================================
// Types
// ============================================================================

/** Input for creating a direct sale (validated via Zod schema) */
export interface CreateDirectSaleInput {
  /** Optional customer ID — null/absent means walk-in */
  customerId?: string | null
  /** Payment method */
  paymentMethod: 'cash' | 'card'
  /** Line items being purchased */
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
    discountPercent?: number | null
  }>
}

/** Result returned after a successful sale creation */
export interface SaleResult {
  /** The created sale header */
  sale: typeof sales.$inferSelect
  /** The created payment record */
  payment: typeof payments.$inferSelect
  /** All line items for this sale */
  lineItems: typeof saleLineItems.$inferSelect[]
