// Use in-memory DB for tests, file-based DB otherwise
const isTest = process.env.NODE_ENV === 'test' || process.env.VITEST === 'true'
const DB_PATH = isTest ? ':memory:' : path.join(process.cwd(), '..', 'data', 'database.db')

let sqliteDb: Database.Database

if (isTest) {
  // In-memory database for tests — completely isolated, no disk writes
  sqliteDb = new Database(':memory:')
} else {
  // Ensure data directory exists
  const dataDir = path.dirname(DB_PATH)
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true })
  }
  // Open database synchronously (much faster than sql.js)
  sqliteDb = new Database(DB_PATH)
}

// Enable WAL mode for better performance with concurrent reads/writes
sqliteDb.pragma('journal_mode = WAL')

